INSERT INTO SACH
VALUES ('CF01',
		'Cranford',
		'Elizabeth Gaskell’s portrait of kindness, compassion, and hope' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + 'Cranford depicts the lives and preoccupations of the inhabitants of a small village - their petty snobberies, appetite for gossip, and loyal support for each other in times of need This is a community that runs on cooperation and gossip, at the very heart of which are the daughters of the former rector: Miss Deborah Jenkyns and her sister Miss Matty, But domestic peace is constantly threatened in the form of financial disaster, imagined burglaries, tragic accidents, and the reapparance of long-lost relatives. to Lady Glenmire, who shocks everyone by marrying the doctor. When men do appear, such as modern Captain Brown or Matty’s suitor from the past, they bring disruption and excitement to the everyday life of Cranford.' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + 'In her introduction, Patricia Ingham places the novel in its literary and historical context, and discusses the theme of female friendship and Gaskell’s narrative technique. This edition also contains an account of Gaskell’s childhood in Knutsford, on which Cranford is based, appendices on fashion and domestic duties supplemented by illustrations, a chronology of Gaskell’s life and works, suggestions for further reading, and explanatory notes.',
		'Elizabeth Gaskell',
		'Penguin Classics',
		'20060425',
		'Digital',
		NULL,
		'AVAILABLE',
		'~/Images/Books/Cranford.jpeg')

