INSERT INTO SACH
VALUES ('FM01',
		'Forgive Me',
		'Today is Leonard Peacock’s birthday. It is also the day he hides a gun in his backpack. Because today is the day he will kill his former best friend, and then himself, with his grandfather’s P-38 pistol.' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + 'But first he must say good-bye to the four people who matter most to him: his Humphrey Bogart-obsessed next-door neighbor, Walt; his classmate, Baback, a violin virtuoso; Lauren, the Christian homeschooler he has a crush on; and Herr Silverman, who teaches the high school’s class on the Holocaust. Speaking to each in turn, Leonard slowly reveals his secrets as the hours tick by and the moment of truth approaches.' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + 'In this riveting look at a day in the life of a disturbed teenage boy, acclaimed author Matthew Quick unflinchingly examines the impossible choices that must be made—and the light in us all that never goes out.',
		'Leonard Peacock',
		'Little, Brown Books',
		'20130813',
		'Digital',
		NULL,
		'AVAILABLE',
		'~/Images/Books/ForgiveMe.jpeg')

