INSERT INTO SACH
VALUES ('PN01',
		'Pnin',
		'One of the best-loved of Nabokov’s novels, Pnin features his funniest and most heart-rending character. Professor Timofey Pnin is a haplessly disoriented Russian émigré precariously employed on an American college campus in the 1950s. Pnin struggles to maintain his dignity through a series of comic and sad misunderstandings, all the while falling victim both to subtle academic conspiracies and to the manipulations of a deliberately unreliable narrator.' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + 'Initially an almost grotesquely comic figure, Pnin gradually grows in stature by contrast with those who laugh at him. Whether taking the wrong train to deliver a lecture in a language he has not mastered or throwing a faculty party during which he learns he is losing his job, the gently preposterous hero of this enchanting novel evokes the reader’s deepest protective instinct.' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + 'Serialized in The New Yorker and published in book form in 1957, Pnin brought Nabokov both his first National Book Award nomination and hitherto unprecedented popularity.',
		'Vladimir Nabokov',
		'Everymans Library',
		'20040406',
		'Digital',
		NULL,
		'AVAILABLE',
		'~/Images/Books/Pnin.jpeg')

INSERT INTO SACH
VALUES ('PN02',
		'Pnin',
		'One of the best-loved of Nabokov’s novels, Pnin features his funniest and most heart-rending character. Professor Timofey Pnin is a haplessly disoriented Russian émigré precariously employed on an American college campus in the 1950s. Pnin struggles to maintain his dignity through a series of comic and sad misunderstandings, all the while falling victim both to subtle academic conspiracies and to the manipulations of a deliberately unreliable narrator.' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + 'Initially an almost grotesquely comic figure, Pnin gradually grows in stature by contrast with those who laugh at him. Whether taking the wrong train to deliver a lecture in a language he has not mastered or throwing a faculty party during which he learns he is losing his job, the gently preposterous hero of this enchanting novel evokes the reader’s deepest protective instinct.' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + 'Serialized in The New Yorker and published in book form in 1957, Pnin brought Nabokov both his first National Book Award nomination and hitherto unprecedented popularity.',
		'Vladimir Nabokov',
		'Everymans Library',
		'20040406',
		'Digital',
		NULL,
		'AVAILABLE',
		'~/Images/Books/Pnin.jpeg')

INSERT INTO SACH
VALUES ('PN03',
		'Pnin',
		'One of the best-loved of Nabokov’s novels, Pnin features his funniest and most heart-rending character. Professor Timofey Pnin is a haplessly disoriented Russian émigré precariously employed on an American college campus in the 1950s. Pnin struggles to maintain his dignity through a series of comic and sad misunderstandings, all the while falling victim both to subtle academic conspiracies and to the manipulations of a deliberately unreliable narrator.' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + 'Initially an almost grotesquely comic figure, Pnin gradually grows in stature by contrast with those who laugh at him. Whether taking the wrong train to deliver a lecture in a language he has not mastered or throwing a faculty party during which he learns he is losing his job, the gently preposterous hero of this enchanting novel evokes the reader’s deepest protective instinct.' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + 'Serialized in The New Yorker and published in book form in 1957, Pnin brought Nabokov both his first National Book Award nomination and hitherto unprecedented popularity.',
		'Vladimir Nabokov',
		'Everymans Library',
		'20040406',
		'Digital',
		NULL,
		'AVAILABLE',
		'~/Images/Books/Pnin.jpeg')

INSERT INTO SACH
VALUES ('RG01',
		'Rules for Ghosting',
		'Rule #1: They can’t speak.' + CHAR(13) + CHAR(10) + 'Rule #2: They can’t move.' + CHAR(13) + CHAR(10) + 'Rule #3: They can’t hurt you.' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + 'Ezra Friedman sees ghosts, which made growing up in a funeral home a bit complicated. It might have been easier if his grandfather’s ghost didn’t give him such scathing looks of disapproval as he went through a second, HRT-induced puberty, or if he didn’t have the pressure of all those relatives—living and dead—judging every choice he makes. It’s no wonder that Ezra runs as far away from the family business as humanly possible.' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + 'But when the floor of his dream job drops out from under him and his mother uses the family Passover seder to tell everyone that she’s running away with the rabbi’s wife, Ezra finds himself back in the thick of it. With his parents’ marriage imploding and the Friedman Family Memorial Chapel on the brink of financial ruin, Ezra agrees to step into his mother’s shoes and help out . . . which means long days surrounded by ghosts that no one else can see.' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + 'And then there’s his unfortunate crush on Jonathan, the handsome funeral home volunteer who just happens to live downstairs from Ezra’s new apartment . . . and the appearance of the ghost of Jonathan’s gone-too-soon husband, Ben, who is breaking every spectral rule Ezra knows.' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + 'Because Ben can speak. He can move. And as Ezra tries to keep his family together and his heart from getting broken, he quickly realizes that there’s more than one way to be haunted—and more than one way to become a ghost.',
		'Shelly Jay Shore',
		'Dell',
		'20240820',
		'Digital',
		NULL,
		'AVAILABLE',
		'~/Images/Books/RulesforGhosting.jpeg')

