INSERT INTO SACH
VALUES ('SF01',
		'The Empress of Salt and Fortune',
		'A young royal from the far north is sent south for a political marriage in an empire reminiscent of imperial China. Her brothers are dead, her armies and their war mammoths long defeated and caged behind their borders. Alone and sometimes reviled, she must choose her allies carefully.' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + 'Rabbit, a handmaiden, sold by her parents to the palace for the lack of five baskets of dye, befriends the emperor’s lonely new wife and gets more than she bargained for.' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + 'At once feminist high fantasy and an indictment of monarchy, this evocative debut follows the rise of the empress In-yo, who has few resources and fewer friends. She’s a northern daughter in a mage-made summer exile, but she will bend history to her will and bring down her enemies, piece by piece.',
		'Nghi Vo',
		'Tor.com',
		'20200324',
		'Digital',
		NULL,
		'AVAILABLE',
		'~/Images/Books/TheEmpressofSaltandFortune.jpeg')

