INSERT INTO SACH
VALUES ('TO01',
		'The One',
		'How far would you go to find The One?' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + 'A simple DNA test is all it takes. Just a quick mouth swab and soon you’ll be matched with your perfect partner the one you are genetically made for.' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + 'That’s the promise made by Match Your DNA. A decade ago, the company announced that they had found the gene that pairs each of us with our soul mate. Since then, millions of people around the world have been matched. But the discovery has its downsides: test results have led to the breakup of countless relationships and upended the traditional ideas of dating, romance and love.' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + 'Now five very different people have received the notification that they’ve been “Matched.” They’re each about to meet their one true love. But “happily ever after” isn’t guaranteed for everyone. Because even soul mates have secrets. And some are more shocking than others…' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + 'A word-of-mouth hit in the United Kingdom, The One is a fascinating novel that shows how even the simplest discoveries can have complicated consequences.',
		'John Marrs',
		'Hanover Square Press',
		'20180301',
		'Digital',
		NULL,
		'AVAILABLE',
		'~/Images/Books/TheOne.jpeg')

