INSERT INTO SACH
VALUES ('WM01',
		'The Wee Free Men',
		'"Another world is colliding with this one," said the toad. "All the monsters are coming back."' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + '"Why?" said Tiffany.' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + '"There’s no one to stop them."' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + 'There was silence for a moment.' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + 'Then Tiffany said, "There’s me."' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + 'Armed only with a frying pan and her common sense, Tiffany Aching, a young witch-to-be, is all that stands between the monsters of Fairyland and the warm, green Chalk country that is her home. Forced into Fairyland to seek her kidnapped brother, Tiffany allies herself with the Chalk’s local Nac Mac Feegle - aka the Wee Free Men - a clan of sheep-stealing, sword-wielding, six-inch-high blue men who are as fierce as they are funny. Together they battle through an eerie and ever-shifting landscape, fighting brutal flying fairies, dream-spinning dromes, and grimhounds - black dogs with eyes of fire and teeth of razors - before ultimately confronting the Queen of the Elves, absolute ruler of a world in which reality intertwines with nightmare. And in the final showdown, Tiffany must face her cruel power alone...' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + 'In a riveting narrative that is equal parts suspense and humor, Carnegie Medalist Terry Pratchett returns to his internationally popular Discworld with a breathtaking tale certain to leave fans, new and old, enthralled.',
		'Terry Pratchett',
		'HarperTrophy',
		'20040101',
		'Digital',
		NULL,
		'AVAILABLE',
		'~/Images/Books/TheWeeFreeMen.jpeg')

