INSERT INTO SACH
VALUES ('KG03',
		'True History of the Kelly Gang',
		'“I lost my own father at 12 yr. of age and know what it is to be raised on lies and silences my dear daughter you are presently too young to understand a word I write but this history is for you and will contain no single lie may I burn in Hell if I speak false.”' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + 'In True History of the Kelly Gang, the legendary Ned Kelly speaks for himself, scribbling his narrative on errant scraps of paper in semiliterate but magically descriptive prose as he flees from the police. To his pursuers, Kelly is nothing but a monstrous criminal, a thief and a murderer. To his own people, the lowly class of ordinary Australians, the bushranger is a hero, defying the authority of the English to direct their lives. Indentured by his bootlegger mother to a famous horse thief (who was also her lover), Ned saw his first prison cell at 15 and by the age of 26 had become the most wanted man in the wild colony of Victoria, taking over whole towns and defying the law until he was finally captured and hanged. Here is a classic outlaw tale, made alive by the skill of a great novelist.',
		'Peter Carey',
		'Vintage',
		'20011204',
		'Digital',
		NULL,
		'AVAILABLE',
		'~/Images/Books/TrueHistoryoftheKellyGang.jpeg')

INSERT INTO SACH
VALUES ('WD01',
		'Walden',
		'Originally published in 1854, Walden; or, Life in the Woods, is a vivid account of the time that Henry D. Thoreau lived alone in a secluded cabin at Walden Pond. It is one of the most influential and compelling books in American literature. This new paperback edition-introduced by noted American writer John Updike-celebrates the 150th anniversary of this classic work. Much of Walden’s material is derived from Thoreau’s journals and contains such engaging pieces as "Reading" and "The Pond in the Winter" Other famous sections involve Thoreau’s visits with a Canadian woodcutter and with an Irish family, a trip to Concord, and a description of his bean field. This is the complete and authoritative text of Walden-as close to Thoreau’s original intention as all available evidence allows. For the student and for the general reader, this is the ideal presentation of Thoreau’s great document of social criticism and dissent.',
		'Henry David Thoreau',
		'Princeton University Press',
		'20040418',
		'Digital',
		NULL,
		'AVAILABLE',
		'~/Images/Books/Walden.jpeg')

